    }
    map['mime_type'] = Variable<String>(mimeType);
    if (!nullToAbsent || width != null) {
      map['width'] = Variable<int>(width);
    }
    if (!nullToAbsent || height != null) {
      map['height'] = Variable<int>(height);
    }
    map['byte_size'] = Variable<int>(byteSize);
    map['stored_path'] = Variable<String>(storedPath);
    if (!nullToAbsent || sourceFileId != null) {
      map['source_file_id'] = Variable<int>(sourceFileId);
    }
    if (!nullToAbsent || sourceDescription != null) {
      map['source_description'] = Variable<String>(sourceDescription);
    }
    if (!nullToAbsent || dominantColor != null) {
      map['dominant_color'] = Variable<int>(dominantColor);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  ImagesCompanion toCompanion(bool nullToAbsent) {
    return ImagesCompanion(
