class Artist extends DataClass implements Insertable<Artist> {
  final int id;

  /// The canonical, true name, displayed as-is.
  final String name;

  /// [name] normalised for matching: case-folded, width-folded, accents and
  /// punctuation stripped. Never displayed. See `domain/text/normalize.dart`.
  final String nameKey;

  /// Optional explicit sort name ("Beatles, The").
  final String? sortName;
  final ArtistKind kind;

  /// Free-text qualifier separating same-named artists ("UK punk band").
  final String? disambiguation;

  /// Markdown biography / notes.
  final String? description;
  final int? imageId;

  /// When true, the credit splitter must never break this name apart, even
  /// though it contains what looks like a separator. This is what keeps
  /// "AC/DC", "Simon & Garfunkel" and "Earth, Wind & Fire" whole.
  final bool neverSplit;

  /// Set once the user has reviewed this artist. Verified rows are never
  /// silently rewritten by a rescan.
  final bool isVerified;
  final bool isFavorite;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Artist({
    required this.id,
    required this.name,
    required this.nameKey,
    this.sortName,
    required this.kind,
    this.disambiguation,
    this.description,
    this.imageId,
    required this.neverSplit,
    required this.isVerified,
    required this.isFavorite,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['name'] = Variable<String>(name);
    map['name_key'] = Variable<String>(nameKey);
    if (!nullToAbsent || sortName != null) {
      map['sort_name'] = Variable<String>(sortName);
    }
    {
      map['kind'] = Variable<String>($ArtistsTable.$converterkind.toSql(kind));
    }
    if (!nullToAbsent || disambiguation != null) {
      map['disambiguation'] = Variable<String>(disambiguation);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || imageId != null) {
      map['image_id'] = Variable<int>(imageId);
    }
    map['never_split'] = Variable<bool>(neverSplit);
    map['is_verified'] = Variable<bool>(isVerified);
    map['is_favorite'] = Variable<bool>(isFavorite);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ArtistsCompanion toCompanion(bool nullToAbsent) {
    return ArtistsCompanion(
      id: Value(id),
      name: Value(name),
      nameKey: Value(nameKey),
      sortName: sortName == null && nullToAbsent
          ? const Value.absent()
          : Value(sortName),
      kind: Value(kind),
      disambiguation: disambiguation == null && nullToAbsent
          ? const Value.absent()
          : Value(disambiguation),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      imageId: imageId == null && nullToAbsent
          ? const Value.absent()
          : Value(imageId),
      neverSplit: Value(neverSplit),
      isVerified: Value(isVerified),
      isFavorite: Value(isFavorite),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Artist.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Artist(
      id: serializer.fromJson<int>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      nameKey: serializer.fromJson<String>(json['nameKey']),
      sortName: serializer.fromJson<String?>(json['sortName']),
      kind: $ArtistsTable.$converterkind.fromJson(
        serializer.fromJson<String>(json['kind']),
      ),
      disambiguation: serializer.fromJson<String?>(json['disambiguation']),
      description: serializer.fromJson<String?>(json['description']),
      imageId: serializer.fromJson<int?>(json['imageId']),
      neverSplit: serializer.fromJson<bool>(json['neverSplit']),
      isVerified: serializer.fromJson<bool>(json['isVerified']),
      isFavorite: serializer.fromJson<bool>(json['isFavorite']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'name': serializer.toJson<String>(name),
      'nameKey': serializer.toJson<String>(nameKey),
      'sortName': serializer.toJson<String?>(sortName),
      'kind': serializer.toJson<String>(
        $ArtistsTable.$converterkind.toJson(kind),
      ),
      'disambiguation': serializer.toJson<String?>(disambiguation),
      'description': serializer.toJson<String?>(description),
      'imageId': serializer.toJson<int?>(imageId),
      'neverSplit': serializer.toJson<bool>(neverSplit),
      'isVerified': serializer.toJson<bool>(isVerified),
      'isFavorite': serializer.toJson<bool>(isFavorite),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
