    Value<String?> sortName = const Value.absent(),
    ArtistKind? kind,
    Value<String?> disambiguation = const Value.absent(),
    Value<String?> description = const Value.absent(),
    Value<int?> imageId = const Value.absent(),
    bool? neverSplit,
    bool? isVerified,
    bool? isFavorite,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Artist(
    id: id ?? this.id,
    name: name ?? this.name,
    nameKey: nameKey ?? this.nameKey,
    sortName: sortName.present ? sortName.value : this.sortName,
    kind: kind ?? this.kind,
    disambiguation: disambiguation.present
        ? disambiguation.value
        : this.disambiguation,
    description: description.present ? description.value : this.description,
    imageId: imageId.present ? imageId.value : this.imageId,
    neverSplit: neverSplit ?? this.neverSplit,
    isVerified: isVerified ?? this.isVerified,
    isFavorite: isFavorite ?? this.isFavorite,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Artist copyWithCompanion(ArtistsCompanion data) {
    return Artist(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      nameKey: data.nameKey.present ? data.nameKey.value : this.nameKey,
      sortName: data.sortName.present ? data.sortName.value : this.sortName,
      kind: data.kind.present ? data.kind.value : this.kind,
      disambiguation: data.disambiguation.present
          ? data.disambiguation.value
          : this.disambiguation,
      description: data.description.present
          ? data.description.value
          : this.description,
      imageId: data.imageId.present ? data.imageId.value : this.imageId,
      neverSplit: data.neverSplit.present
          ? data.neverSplit.value
          : this.neverSplit,
      isVerified: data.isVerified.present
          ? data.isVerified.value
          : this.isVerified,
      isFavorite: data.isFavorite.present
          ? data.isFavorite.value
          : this.isFavorite,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Artist(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('nameKey: $nameKey, ')
          ..write('sortName: $sortName, ')
          ..write('kind: $kind, ')
          ..write('disambiguation: $disambiguation, ')
          ..write('description: $description, ')
          ..write('imageId: $imageId, ')
          ..write('neverSplit: $neverSplit, ')
          ..write('isVerified: $isVerified, ')
          ..write('isFavorite: $isFavorite, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    name,
    nameKey,
    sortName,
    kind,
    disambiguation,
    description,
    imageId,
    neverSplit,
    isVerified,
    isFavorite,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Artist &&
          other.id == this.id &&
          other.name == this.name &&
          other.nameKey == this.nameKey &&
          other.sortName == this.sortName &&
          other.kind == this.kind &&
          other.disambiguation == this.disambiguation &&
          other.description == this.description &&
          other.imageId == this.imageId &&
          other.neverSplit == this.neverSplit &&
          other.isVerified == this.isVerified &&
          other.isFavorite == this.isFavorite &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
