class Album extends DataClass implements Insertable<Album> {
  final int id;
  final String title;

  /// Normalised [title], for matching.
  final String nameKey;
  final String? sortTitle;
  final AlbumKind kind;

  /// Release date, stored as separate parts because tags routinely carry only
  /// a year, and inventing a month and day would be a lie.
  final int? releaseYear;
  final int? releaseMonth;
  final int? releaseDay;

  /// The album's primary artist. Null for genuine various-artists releases.
  final int? albumArtistId;
  final bool isVariousArtists;
  final int? totalTracks;
  final int? totalDiscs;
  final String? description;
  final int? imageId;

  /// Directory the album was discovered in. A hint for re-matching and for
  /// finding sidecar artwork, not an authority.
  final String? folderHint;
  final String? label;
  final String? catalogNumber;
  final bool isVerified;
  final bool isFavorite;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Album({
    required this.id,
    required this.title,
    required this.nameKey,
    this.sortTitle,
    required this.kind,
    this.releaseYear,
    this.releaseMonth,
    this.releaseDay,
    this.albumArtistId,
    required this.isVariousArtists,
    this.totalTracks,
    this.totalDiscs,
    this.description,
    this.imageId,
    this.folderHint,
    this.label,
    this.catalogNumber,
    required this.isVerified,
    required this.isFavorite,
    required this.createdAt,
    required this.updatedAt,
  });
