class Track extends DataClass implements Insertable<Track> {
  final int id;
  final String title;

  /// Normalised [title], for matching and duplicate detection.
  final String nameKey;
  final String? sortTitle;
  final int? albumId;
  final int? discNo;
  final int? trackNo;
  final int? durationMs;
  final int? releaseYear;
  final double? bpm;

  /// Musical key as tagged ("F#m", "8A").
  final String? initialKey;
  final String? comment;

  /// Markdown notes the user attached to this track.
  final String? notes;

  /// 0-100. Null means unrated, which is distinct from a rating of zero.
  final int? rating;
  final bool isFavorite;
  final int playCount;
  final int skipCount;
  final DateTime? lastPlayedAt;

  /// Track-specific artwork, which wins over the album's and the artist's.
  final int? imageId;

  /// Which file to play when several hold this track. Null means "decide by
  /// the quality preference in settings".
  final int? preferredFileId;
  final bool isVerified;
  final DateTime addedAt;
  final DateTime updatedAt;
  const Track({
    required this.id,
    required this.title,
    required this.nameKey,
    this.sortTitle,
    this.albumId,
    this.discNo,
    this.trackNo,
    this.durationMs,
    this.releaseYear,
    this.bpm,
    this.initialKey,
    this.comment,
    this.notes,
    this.rating,
    required this.isFavorite,
    required this.playCount,
    required this.skipCount,
    this.lastPlayedAt,
    this.imageId,
    this.preferredFileId,
    required this.isVerified,
    required this.addedAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['title'] = Variable<String>(title);
    map['name_key'] = Variable<String>(nameKey);
    if (!nullToAbsent || sortTitle != null) {
      map['sort_title'] = Variable<String>(sortTitle);
    }
    if (!nullToAbsent || albumId != null) {
      map['album_id'] = Variable<int>(albumId);
    }
    if (!nullToAbsent || discNo != null) {
      map['disc_no'] = Variable<int>(discNo);
    }
    if (!nullToAbsent || trackNo != null) {
      map['track_no'] = Variable<int>(trackNo);
    }
    if (!nullToAbsent || durationMs != null) {
      map['duration_ms'] = Variable<int>(durationMs);
    }
    if (!nullToAbsent || releaseYear != null) {
      map['release_year'] = Variable<int>(releaseYear);
    }
    if (!nullToAbsent || bpm != null) {
      map['bpm'] = Variable<double>(bpm);
    }
    if (!nullToAbsent || initialKey != null) {
      map['initial_key'] = Variable<String>(initialKey);
    }
    if (!nullToAbsent || comment != null) {
      map['comment'] = Variable<String>(comment);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || rating != null) {
      map['rating'] = Variable<int>(rating);
    }
    map['is_favorite'] = Variable<bool>(isFavorite);
    map['play_count'] = Variable<int>(playCount);
    map['skip_count'] = Variable<int>(skipCount);
    if (!nullToAbsent || lastPlayedAt != null) {
      map['last_played_at'] = Variable<DateTime>(lastPlayedAt);
    }
    if (!nullToAbsent || imageId != null) {
      map['image_id'] = Variable<int>(imageId);
    }
    if (!nullToAbsent || preferredFileId != null) {
      map['preferred_file_id'] = Variable<int>(preferredFileId);
    }
    map['is_verified'] = Variable<bool>(isVerified);
    map['added_at'] = Variable<DateTime>(addedAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  TracksCompanion toCompanion(bool nullToAbsent) {
    return TracksCompanion(
      id: Value(id),
      title: Value(title),
      nameKey: Value(nameKey),
      sortTitle: sortTitle == null && nullToAbsent
          ? const Value.absent()
          : Value(sortTitle),
      albumId: albumId == null && nullToAbsent
          ? const Value.absent()
          : Value(albumId),
      discNo: discNo == null && nullToAbsent
          ? const Value.absent()
          : Value(discNo),
      trackNo: trackNo == null && nullToAbsent
          ? const Value.absent()
          : Value(trackNo),
      durationMs: durationMs == null && nullToAbsent
          ? const Value.absent()
          : Value(durationMs),
      releaseYear: releaseYear == null && nullToAbsent
          ? const Value.absent()
          : Value(releaseYear),
      bpm: bpm == null && nullToAbsent ? const Value.absent() : Value(bpm),
      initialKey: initialKey == null && nullToAbsent
          ? const Value.absent()
          : Value(initialKey),
      comment: comment == null && nullToAbsent
          ? const Value.absent()
          : Value(comment),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      rating: rating == null && nullToAbsent
          ? const Value.absent()
          : Value(rating),
      isFavorite: Value(isFavorite),
      playCount: Value(playCount),
      skipCount: Value(skipCount),
      lastPlayedAt: lastPlayedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastPlayedAt),
      imageId: imageId == null && nullToAbsent
          ? const Value.absent()
          : Value(imageId),
      preferredFileId: preferredFileId == null && nullToAbsent
          ? const Value.absent()
          : Value(preferredFileId),
      isVerified: Value(isVerified),
      addedAt: Value(addedAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Track.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Track(
      id: serializer.fromJson<int>(json['id']),
      title: serializer.fromJson<String>(json['title']),
      nameKey: serializer.fromJson<String>(json['nameKey']),
      sortTitle: serializer.fromJson<String?>(json['sortTitle']),
      albumId: serializer.fromJson<int?>(json['albumId']),
      discNo: serializer.fromJson<int?>(json['discNo']),
      trackNo: serializer.fromJson<int?>(json['trackNo']),
      durationMs: serializer.fromJson<int?>(json['durationMs']),
      releaseYear: serializer.fromJson<int?>(json['releaseYear']),
      bpm: serializer.fromJson<double?>(json['bpm']),
      initialKey: serializer.fromJson<String?>(json['initialKey']),
      comment: serializer.fromJson<String?>(json['comment']),
      notes: serializer.fromJson<String?>(json['notes']),
      rating: serializer.fromJson<int?>(json['rating']),
      isFavorite: serializer.fromJson<bool>(json['isFavorite']),
      playCount: serializer.fromJson<int>(json['playCount']),
      skipCount: serializer.fromJson<int>(json['skipCount']),
      lastPlayedAt: serializer.fromJson<DateTime?>(json['lastPlayedAt']),
      imageId: serializer.fromJson<int?>(json['imageId']),
      preferredFileId: serializer.fromJson<int?>(json['preferredFileId']),
      isVerified: serializer.fromJson<bool>(json['isVerified']),
      addedAt: serializer.fromJson<DateTime>(json['addedAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'title': serializer.toJson<String>(title),
      'nameKey': serializer.toJson<String>(nameKey),
      'sortTitle': serializer.toJson<String?>(sortTitle),
      'albumId': serializer.toJson<int?>(albumId),
      'discNo': serializer.toJson<int?>(discNo),
      'trackNo': serializer.toJson<int?>(trackNo),
      'durationMs': serializer.toJson<int?>(durationMs),
      'releaseYear': serializer.toJson<int?>(releaseYear),
      'bpm': serializer.toJson<double?>(bpm),
      'initialKey': serializer.toJson<String?>(initialKey),
      'comment': serializer.toJson<String?>(comment),
      'notes': serializer.toJson<String?>(notes),
      'rating': serializer.toJson<int?>(rating),
      'isFavorite': serializer.toJson<bool>(isFavorite),
      'playCount': serializer.toJson<int>(playCount),
      'skipCount': serializer.toJson<int>(skipCount),
      'lastPlayedAt': serializer.toJson<DateTime?>(lastPlayedAt),
      'imageId': serializer.toJson<int?>(imageId),
      'preferredFileId': serializer.toJson<int?>(preferredFileId),
      'isVerified': serializer.toJson<bool>(isVerified),
      'addedAt': serializer.toJson<DateTime>(addedAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Track copyWith({
    int? id,
    String? title,
    String? nameKey,
    Value<String?> sortTitle = const Value.absent(),
    Value<int?> albumId = const Value.absent(),
    Value<int?> discNo = const Value.absent(),
    Value<int?> trackNo = const Value.absent(),
    Value<int?> durationMs = const Value.absent(),
