class MediaFile extends DataClass implements Insertable<MediaFile> {
  final int id;
  final int folderId;

  /// Path relative to the owning folder, using forward slashes.
  ///
  /// Storing it relative means re-rooting a whole library (a drive letter
  /// change, a moved collection) is a single update to the folder row.
  final String relativePath;
  final String fileName;

  /// Lower-case, without the dot.
  final String extension;
  final int sizeBytes;
  final DateTime modifiedAt;

  /// Hash of the audio payload, excluding tag blocks. Stable across retagging.
  final String? contentKey;

  /// Cheap hash of size plus head and tail bytes.
  final String? quickKey;

  /// Hash of the tag block, so a rescan can tell "tags changed" from
  /// "nothing changed" without a full reparse.
  final String? tagsHash;

  /// NTFS volume serial number, when obtainable.
  final int? volumeSerial;

  /// NTFS file index, as a hex string (it can exceed 64 bits on ReFS).
  final String? fileIndex;
  final String? codec;
  final int? bitrate;
  final int? sampleRate;
  final int? channels;
  final int? bitDepth;
  final bool lossless;
  final int? durationMs;

  /// ReplayGain track gain in dB, when the file carries it.
  final double? replayGainDb;
  final double? replayGainPeak;
  final FileStatus status;
  final int? trackId;
  final DateTime firstSeenAt;
  final DateTime lastSeenAt;
  final DateTime? lastIndexedAt;

  /// Populated when [status] is [FileStatus.unreadable].
  final String? errorMessage;
  const MediaFile({
    required this.id,
    required this.folderId,
    required this.relativePath,
    required this.fileName,
    required this.extension,
    required this.sizeBytes,
    required this.modifiedAt,
    this.contentKey,
    this.quickKey,
    this.tagsHash,
    this.volumeSerial,
    this.fileIndex,
    this.codec,
    this.bitrate,
    this.sampleRate,
    this.channels,
    this.bitDepth,
    required this.lossless,
    this.durationMs,
    this.replayGainDb,
    this.replayGainPeak,
    required this.status,
    this.trackId,
    required this.firstSeenAt,
    required this.lastSeenAt,
    this.lastIndexedAt,
    this.errorMessage,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['folder_id'] = Variable<int>(folderId);
    map['relative_path'] = Variable<String>(relativePath);
    map['file_name'] = Variable<String>(fileName);
    map['extension'] = Variable<String>(extension);
    map['size_bytes'] = Variable<int>(sizeBytes);
    map['modified_at'] = Variable<DateTime>(modifiedAt);
    if (!nullToAbsent || contentKey != null) {
      map['content_key'] = Variable<String>(contentKey);
    }
    if (!nullToAbsent || quickKey != null) {
      map['quick_key'] = Variable<String>(quickKey);
    }
    if (!nullToAbsent || tagsHash != null) {
      map['tags_hash'] = Variable<String>(tagsHash);
    }
    if (!nullToAbsent || volumeSerial != null) {
      map['volume_serial'] = Variable<int>(volumeSerial);
    }
    if (!nullToAbsent || fileIndex != null) {
      map['file_index'] = Variable<String>(fileIndex);
    }
    if (!nullToAbsent || codec != null) {
      map['codec'] = Variable<String>(codec);
    }
    if (!nullToAbsent || bitrate != null) {
      map['bitrate'] = Variable<int>(bitrate);
    }
    if (!nullToAbsent || sampleRate != null) {
      map['sample_rate'] = Variable<int>(sampleRate);
    }
    if (!nullToAbsent || channels != null) {
      map['channels'] = Variable<int>(channels);
    }
    if (!nullToAbsent || bitDepth != null) {
      map['bit_depth'] = Variable<int>(bitDepth);
    }
    map['lossless'] = Variable<bool>(lossless);
    if (!nullToAbsent || durationMs != null) {
      map['duration_ms'] = Variable<int>(durationMs);
    }
    if (!nullToAbsent || replayGainDb != null) {
      map['replay_gain_db'] = Variable<double>(replayGainDb);
    }
    if (!nullToAbsent || replayGainPeak != null) {
      map['replay_gain_peak'] = Variable<double>(replayGainPeak);
    }
    {
      map['status'] = Variable<String>(
        $MediaFilesTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || trackId != null) {
      map['track_id'] = Variable<int>(trackId);
    }
    map['first_seen_at'] = Variable<DateTime>(firstSeenAt);
    map['last_seen_at'] = Variable<DateTime>(lastSeenAt);
    if (!nullToAbsent || lastIndexedAt != null) {
      map['last_indexed_at'] = Variable<DateTime>(lastIndexedAt);
    }
    if (!nullToAbsent || errorMessage != null) {
      map['error_message'] = Variable<String>(errorMessage);
    }
    return map;
  }

