    if (!nullToAbsent || unshuffledPosition != null) {
      map['unshuffled_position'] = Variable<int>(unshuffledPosition);
    }
    map['added_at'] = Variable<DateTime>(addedAt);
    if (!nullToAbsent || playedAt != null) {
      map['played_at'] = Variable<DateTime>(playedAt);
    }
    return map;
  }

  QueueItemsCompanion toCompanion(bool nullToAbsent) {
    return QueueItemsCompanion(
      id: Value(id),
      trackId: Value(trackId),
      position: Value(position),
      source: Value(source),
      sourceRefId: sourceRefId == null && nullToAbsent
          ? const Value.absent()
          : Value(sourceRefId),
      unshuffledPosition: unshuffledPosition == null && nullToAbsent
