class SeparatorToken extends DataClass implements Insertable<SeparatorToken> {
  final int id;

  /// The literal token, matched case-insensitively.
  final String token;
  final SeparatorKind kind;

  /// When true, the token only counts as a separator if surrounded by
  /// whitespace or string boundaries.
  final bool requiresSpaces;

  /// When true, real artist names are known to contain this token, so the
  /// resolver requires corroborating evidence before splitting on it.
  final bool isAmbiguous;
  final bool enabled;
  final int sortOrder;

  /// True for tokens shipped with the app, so a "reset to defaults" is
  /// possible without discarding the user's own additions.
  final bool isBuiltIn;
  const SeparatorToken({
    required this.id,
    required this.token,
    required this.kind,
    required this.requiresSpaces,
    required this.isAmbiguous,
    required this.enabled,
    required this.sortOrder,
    required this.isBuiltIn,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
