class PendingCredit extends DataClass implements Insertable<PendingCredit> {
  final int id;
  final int trackId;
  final String rawCredit;

  /// JSON array of candidate interpretations, best first, each with a
  /// confidence and the artists it would create or link.
  final String suggestions;
  final DateTime createdAt;
  final DateTime? resolvedAt;
  const PendingCredit({
    required this.id,
    required this.trackId,
    required this.rawCredit,
    required this.suggestions,
    required this.createdAt,
    this.resolvedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['track_id'] = Variable<int>(trackId);
    map['raw_credit'] = Variable<String>(rawCredit);
    map['suggestions'] = Variable<String>(suggestions);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || resolvedAt != null) {
      map['resolved_at'] = Variable<DateTime>(resolvedAt);
    }
    return map;
  }

  PendingCreditsCompanion toCompanion(bool nullToAbsent) {
    return PendingCreditsCompanion(
      id: Value(id),
      trackId: Value(trackId),
      rawCredit: Value(rawCredit),
      suggestions: Value(suggestions),
      createdAt: Value(createdAt),
      resolvedAt: resolvedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(resolvedAt),
    );
  }

  factory PendingCredit.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return PendingCredit(
      id: serializer.fromJson<int>(json['id']),
      trackId: serializer.fromJson<int>(json['trackId']),
      rawCredit: serializer.fromJson<String>(json['rawCredit']),
      suggestions: serializer.fromJson<String>(json['suggestions']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      resolvedAt: serializer.fromJson<DateTime?>(json['resolvedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'trackId': serializer.toJson<int>(trackId),
      'rawCredit': serializer.toJson<String>(rawCredit),
      'suggestions': serializer.toJson<String>(suggestions),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'resolvedAt': serializer.toJson<DateTime?>(resolvedAt),
    };
  }

  PendingCredit copyWith({
    int? id,
    int? trackId,
    String? rawCredit,
    String? suggestions,
    DateTime? createdAt,
    Value<DateTime?> resolvedAt = const Value.absent(),
  }) => PendingCredit(
    id: id ?? this.id,
    trackId: trackId ?? this.trackId,
    rawCredit: rawCredit ?? this.rawCredit,
    suggestions: suggestions ?? this.suggestions,
    createdAt: createdAt ?? this.createdAt,
    resolvedAt: resolvedAt.present ? resolvedAt.value : this.resolvedAt,
  );
  PendingCredit copyWithCompanion(PendingCreditsCompanion data) {
    return PendingCredit(
      id: data.id.present ? data.id.value : this.id,
      trackId: data.trackId.present ? data.trackId.value : this.trackId,
      rawCredit: data.rawCredit.present ? data.rawCredit.value : this.rawCredit,
      suggestions: data.suggestions.present
          ? data.suggestions.value
          : this.suggestions,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      resolvedAt: data.resolvedAt.present
          ? data.resolvedAt.value
          : this.resolvedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('PendingCredit(')
          ..write('id: $id, ')
          ..write('trackId: $trackId, ')
          ..write('rawCredit: $rawCredit, ')
          ..write('suggestions: $suggestions, ')
          ..write('createdAt: $createdAt, ')
          ..write('resolvedAt: $resolvedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode =>
      Object.hash(id, trackId, rawCredit, suggestions, createdAt, resolvedAt);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is PendingCredit &&
          other.id == this.id &&
          other.trackId == this.trackId &&
          other.rawCredit == this.rawCredit &&
          other.suggestions == this.suggestions &&
          other.createdAt == this.createdAt &&
          other.resolvedAt == this.resolvedAt);
}

